package org.apache.commons.io.input;




public abstract class ProxyReader extends FilterReader
{

    public ProxyReader(Reader proxy)
    {
        super(proxy);
    }

    public int read()
        throws IOException
    {
        int c;
        beforeRead(1);
        c = in.read();
        afterRead(c == -1 ? -1 : 1);
        return c;
        IOException e;
        e;
        handleIOException(e);
        return -1;
    }

    public int read(char chr[])
        throws IOException
