public class MyStack {
    private List list = new ArrayList();

    synchronized public void push() {
        try {
            if (list.size() == 1) {
                System.out.println("pushæä½ä¸­çï¼ " + Thread.currentThread().getName() + " çº¿ç¨åwaitç¶æ");
                this.wait();
            }
            list.add(Math.random());
            this.notify();
            System.out.println("push = " + list.size());
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    synchronized public String pop() {
        String returnValue = "";
        try {
            if (list.size() == 0) {
                System.out.println("popæä½ä¸­çï¼ " + Thread.currentThread().getName() + " çº¿ç¨åwaitç¶æ");
                this.wait();
            }
            returnValue = list.get(0) + "  " + Thread.currentThread().getName();
            list.remove(0);
            this.notify();
            System.out.println("pop = " + list.size() + "  Mystackçpopæ¹æ³ä¸­ çº¿ç¨" + Thread.currentThread().getName());
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        return returnValue;
    }
}
