public class Solution {
    public boolean isMatch_1(String s, String p) {
        if (p.length() == 0) return s.length() == 0;
        if (p.length() == 1) {
            if (s.length() != 1) return false;
            return (s.charAt(0) == p.charAt(0)) || (p.charAt(0) == '.');
        }
        if (s.length() != 0 && (p.charAt(0) == s.charAt(0) || (p.charAt(0) == '.'))) {
            if (p.charAt(1) == '*')
                return isMatch(s.substring(1),p) || isMatch(s, p.substring(2));
            return isMatch(s.substring(1), p.substring(1));
        }
        return p.charAt(1) == '*' && isMatch(s, p.substring(2));
    }
    public boolean isMatch_2(String s, String p) {
        if (p.length() == 0) return s.length() == 0;
        int sLen = s.length(), pLen = p.length();
        boolean[][] dp = new boolean[sLen + 1][pLen + 1];
        dp[0][0] = true;
        for (int i = 2; i <= pLen; ++i) {
            dp[0][i] = dp[0][i-2] && p.charAt(i-1) == '*';
        }
        for (int i = 1; i <= sLen; ++i) {
            for (int j = 1; j <= pLen; ++j) {
                char ch1 = s.charAt(i-1), ch2 = p.charAt(j-1);
                if (ch2 != '*') dp[i][j] = dp[i-1][j-1] && (ch1 == ch2 || ch2 == '.');
                else {
                    dp[i][j] = dp[i][j-2];
                    if (ch1 == p.charAt(j-2) || p.charAt(j-2) == '.')
                        dp[i][j] = dp[i][j] | dp[i-1][j];
                }
            }
        }
        return dp[sLen][pLen];
    }
},31

public class Solution {
    public List<List<Integer>> levelOrder_1(TreeNode root) {
        List<List<Integer>> res = new ArrayList<List<Integer>>();
        if (root == null) return res;
        Queue<TreeNode> q = new LinkedList<TreeNode>();
        q.offer(root);
        q.offer(null);
        List<Integer> level = new ArrayList<Integer>();

        while(true) {
            TreeNode node = q.poll();
            if (node != null) {
                level.add(node.val);
                if(node.left!=null) q.offer(node.left);
                if(node.right!=null) q.offer(node.right);
            } else {
                res.add(level);
                level = new ArrayList<Integer>();
                if(q.isEmpty()==true) break;
                q.offer(null);
            }
        }
        return res;
    }

    public List<List<Integer>> levelOrder_2(TreeNode root) {
        List<List<Integer>> res = new ArrayList<List<Integer>>();
        if (root == null) return res;
        levelOrderRe(root, 0, res);
        return res;
    }
    public void levelOrderRe(TreeNode root, int level, List<List<Integer>> res) {
        if(root == null) return;
        if(level == res.size()) res.add(new ArrayList<Integer>());
        res.get(level).add(root.val);
        levelOrderRe(root.left, level+1, res);
        levelOrderRe(root.right,level+1, res);
    }
}
