public class Solution {
    public boolean search_1(int[] A, int target) {
        for (int i = 0; i < A.length; ++i) {
            if (A[i] == target) return true;
        }
        return false;
    }
    public boolean search(int[] A, int target) {
        int left = 0, right = A.length - 1;
        while (left <= right) {
            int mid = (left + right) /2;
            if (A[mid] == target) return true;
            if (A[left] < A[mid]) {
                if (A[left] <= target && target < A[mid]) right = mid - 1;
                else left = mid + 1;
            } else if (A[left] > A[mid]) {
                if (A[mid] < target && target <= A[right]) left = mid + 1;
                else right = mid - 1;
            } else {
                if (A[left] == A[right]) {
                    ++left; --right;
                } else left = mid + 1;
            }
        }
        return false;
    }
},31

public class Solution {
    public List<TreeNode> generateTrees(int n) {
        return generateTreesRe(1, n);
    }
    public List<TreeNode> generateTreesRe(int l, int r) {
        ArrayList<TreeNode> res = new ArrayList<TreeNode>();
        if (l > r) {
            res.add(null);
            return res;
        }
        for (int k = l; k <= r; ++k) {
            List<TreeNode> leftTrees = generateTreesRe(l, k-1);
            List<TreeNode> rightTrees = generateTreesRe(k+1, r);
            for (int i = 0; i < leftTrees.size(); i++) {
                for (int j = 0; j < rightTrees.size(); j++) {
                    TreeNode root = new TreeNode(k);
                    root.left = leftTrees.get(i);
                    root.right = rightTrees.get(j);
                    res.add(root);
                }
            }
        }
        return res;
    }
},31

