        mFileListAdapter.setListItems(data);

        if (isResumed())
            setListShown(true);
        else
            setListShownNoAnimation(true);


    }

    @Override
    public void onLoaderReset(Loader<List<SelectableFile>> loader) {
        mFileListAdapter.clear();
    }
}
