package cn.itcast_06;

public class FinallyTest {
    public static void main(String[] args) {
        System.out.println(returnInt()); }

    public static int returnInt() {
        int n = 10;
        try {
            n = 20;
            System.out.println(10 / 0);
            n = 30;
        } catch (ArithmeticException e) {
            n = 40;
            return n;
        } finally {
            n = 50;
            return n;
        }
        }
}
